cypress_script:
describe('Product Search Functionality', () => {
  it('should display search results for a valid product', () => {
    cy.visit('https://automationexercise.com/products');
    cy.get('#search_product').type('Tshirt');
    cy.get('#submit_search').click();
    cy.url().should('include', 'search');
    cy.get('.google-anno').should('be.visible');
  });
  it('should not change the product list for an empty search', () => {
    cy.visit('https://automationexercise.com/products');
    cy.get('#submit_search').click();
    cy.url().should('eq', 'https://automationexercise.com/products');
    cy.get('#search_product').should('be.visible');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Product Search Functionality', () => {
  test('should display search results for a valid product', async ({ page }) => {
    await page.goto('https://automationexercise.com/products');
    await page.fill('#search_product', 'Tshirt');
    await page.click('#submit_search');
    await expect(page).toHaveURL(/search/);
    await expect(page.locator('.google-anno')).toBeVisible();
  });
  test('should not change the product list for an empty search', async ({ page }) => {
    await page.goto('https://automationexercise.com/products');
    await page.click('#submit_search');
    await expect(page).toHaveURL('https://automationexercise.com/products');
    await expect(page.locator('#search_product')).toBeVisible();
  });
});
